import{_ as a,o as n,c as t,a2 as i}from"./chunks/framework.Cm6XCzck.js";const u=JSON.parse('{"title":"14. Engineering Conclusion","description":"","frontmatter":{},"headers":[],"relativePath":"en/publications/implementation-case-i0.5/part-04.md","filePath":"en/publications/implementation-case-i0.5/part-04.md","lastUpdated":1785916356000}'),o={name:"en/publications/implementation-case-i0.5/part-04.md"};function r(s,e,c,d,p,l){return n(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="_14-engineering-conclusion" tabindex="-1">14. Engineering Conclusion <a class="header-anchor" href="#_14-engineering-conclusion" aria-label="Permalink to &quot;14. Engineering Conclusion&quot;">​</a></h1><p>The public S0.4 corpus converts broad engineering history into a testable, repository-resident baseline. Its Reference Reader passes all 14 synthetic criteria. Against the pinned products, only C14 passes, nine criteria have partial evidence, and four were not run at product-reader level. The result is stronger than an unversioned demonstration but remains weaker than complete or independent conformance.</p><p>The products already contain many write-side and local-control mechanisms. The new generic reader establishes a deterministic read-side reference, while maintained product projection adapters remain the largest shared gap. Product execution of C08, C10, C11, and C12, completion of the other partial outputs, quantified SME deployment cost, and independent reproduction remain separate empirical requirements.</p><h1 id="artifact-availability" tabindex="-1">Artifact Availability <a class="header-anchor" href="#artifact-availability" aria-label="Permalink to &quot;Artifact Availability&quot;">​</a></h1><p>The author-produced S0.4 corpus is public at <a href="https://github.com/joinwell52-AI/joinwell52/tree/main/research/conformance/tmpa-core-s0.4" target="_blank" rel="noreferrer"><code>research/conformance/tmpa-core-s0.4</code></a>. It contains the Reference Reader, executable profile, fixtures, product-evidence assertions, external-run records, criterion results, summaries, logs, and SHA-256 manifest. WP-13 case boundaries and mapping metadata are at <a href="https://github.com/joinwell52-AI/joinwell52/tree/main/research/cases/wp13-multi-agent-fact-check" target="_blank" rel="noreferrer"><code>research/cases/wp13-multi-agent-fact-check</code></a>, and the complete V3 package is published under <code>/evidence/tmpa/i0.5/</code>. There is no separate <code>tmpa-conformance.zip</code>; Git history is the version history.</p><h1 id="data-availability" tabindex="-1">Data Availability <a class="header-anchor" href="#data-availability" aria-label="Permalink to &quot;Data Availability&quot;">​</a></h1><p>The public demonstration exposes selected governance views. Private business data, credentials, and sensitive operational records are not included. The corpus uses selected test paths, hash inventories, and compact fixtures rather than exporting private production data. The WP-13 package contains only the tasks, reports, runtime excerpts, Git patch, and QA results needed for this case; the original private product repository is not distributed with it.</p><h1 id="competing-interests-and-provenance" tabindex="-1">Competing Interests and Provenance <a class="header-anchor" href="#competing-interests-and-provenance" aria-label="Permalink to &quot;Competing Interests and Provenance&quot;">​</a></h1><p>The author is the originator or principal developer of TMPA, FCoP, and CodeFlowMu and is involved in the XiaoDian AI lineage. All baseline results are author-produced. This relationship increases the need for fixed versions, preserved failures, and independent reproduction.</p><h1 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h1><p>[1] FCoP Project. “FCoP — File-based Coordination Protocol,” repository README and architecture stack. GitHub, 2026. <code>https://github.com/joinwell52-AI/FCoP</code>.</p><p>[2] FCoP Project. “FCoP Runtime Specification · Single-Page Complete Edition,” 1.2.x specification line, 2026.</p><p>[3] FCoP Project. “FCoP IPC Envelope” and related machine-readable JSON Schemas, <code>spec/schemas/</code>, 2026.</p><p>[4] Python Package Index. <code>fcop</code> and <code>fcop-mcp</code> distributions, 2026.</p><p>[5] Official MCP Registry. <code>io.github.joinwell52-AI/fcop</code>, <code>fcop-mcp</code> server entry, 2026.</p><p>[6] FCoP Project. “ADR-0031: Governance Alert Layer (GAL).” Accepted 2026-05-11.</p><p>[7] FCoP Project. “ADR-0032: <code>fcop_audit()</code> — Protocol-to-Inspection Compiler.” Accepted 2026-05-12.</p><p>[8] CodeFlowMu. “TMPA Browser” public demonstration. <code>https://demo.chedian.cc/</code>. Snapshot observed 2026-07-29.</p><p>[9] TMPA Project. “TMPA Core S0.4 C01–C14 Conformance Corpus.” Corpus ID <code>tmpa-s0.4-fcop-codeflowmu-20260803</code>, executed 2026-08-03. <code>research/conformance/tmpa-core-s0.4/</code>.</p><p>[10] CodeFlowMu Project. “WP-13 Multi-Agent Fact-Check Publication Evidence V3.” Author-produced evidence snapshot, observed 2026-08-05. <code>research/cases/wp13-multi-agent-fact-check/</code>.</p><h1 id="appendix-a-fcop-end-to-end-artifact-example" tabindex="-1">Appendix A. FCoP End-to-End Artifact Example <a class="header-anchor" href="#appendix-a-fcop-end-to-end-artifact-example" aria-label="Permalink to &quot;Appendix A. FCoP End-to-End Artifact Example&quot;">​</a></h1><p>A TASK is created by PM, claimed and executed by DEV, followed by a separate DEV REPORT and an independent QA REVIEW. The QA review may return <code>needs_human</code> when technical verification passes but production activation changes an authorization boundary.</p><p>The reader reconstructs:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TASK created by PM</span></span>
<span class="line"><span>  ├─ claimed and executed by DEV</span></span>
<span class="line"><span>  ├─ REPORT submitted by DEV</span></span>
<span class="line"><span>  ├─ REVIEW issued by QA: needs_human</span></span>
<span class="line"><span>  ├─ judgment: undetermined</span></span>
<span class="line"><span>  ├─ view: pending_human</span></span>
<span class="line"><span>  ├─ authorized human approval or rejection evidence</span></span>
<span class="line"><span>  └─ final judgment: valid or invalid</span></span></code></pre></div><p>The <code>needs_human</code> node remains in the graph and is queryable. Downstream objects depending on it remain <code>undetermined</code> until an authorized decision object resolves the state. The authoritative record is the source set and transitions, not the rendered view. Reordering input files must not change the reconstructed graph or issue set.</p><h2 id="i0-5-theory-to-implementation-alignment" tabindex="-1">I0.5 Theory-to-Implementation Alignment <a class="header-anchor" href="#i0-5-theory-to-implementation-alignment" aria-label="Permalink to &quot;I0.5 Theory-to-Implementation Alignment&quot;">​</a></h2><p>FCoP is evaluated as a protocol realization of TMPA concepts; CodeFlowMu is evaluated as an engineering system combining protocol roles with Skills, tools, runtime execution, recovery, and interfaces. The report distinguishes probabilistic agent execution evidence from deterministic validation mechanisms, and demonstrated behavior from full Core conformance.</p>`,27)])])}const m=a(o,[["render",r]]);export{u as __pageData,m as default};
